import { AlertTriangle, ArrowDownToLine, ArrowLeft, BadgeCheck, Bookmark, BookmarkMinus, BookMarked, Boxes, Check, CheckCircle2, Ellipsis, Film, Flag, FolderOpen, Gamepad2, Minus, Music2, PackageMinus, PackagePlus, Pencil, Plus, RotateCcw, Search, Send, ShieldCheck, Sparkles, Telescope, Trash2, Wrench, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { ReactNode } from "react";
import { showAuthDialog, useCloudState } from "../cloud";
import { importCustomMappingPackage, uninstallCustomMappingPackage, useCustomMappings } from "../customMappings/registry";
import type { CommunityPackageTag, CommunityProgress, CommunityRelease, CustomMappingPackageRecord } from "../types";

export type LibraryTab = "discover" | "saved" | "installed" | "published" | "moderation";
type InstallState = "install" | "update" | "installed";
type SortOption = "newest" | "name" | "name-desc";
type MenuItem = { label: string; icon: ReactNode; action: () => void; danger?: boolean };
type ChosenThumbnail = { previewUrl: string; thumbnail: { mimeType: string; data: string } };
type ProgressToast = CommunityProgress & { id: string; title: string; status: "progress" | "success" | "error" };

const DISCOVER_THEMES = [
  { id: "surreality", title: "By Surreality", description: "Official mappings from the Surreality team.", color: "#d86b45", icon: BadgeCheck },
  { id: "media", title: "Media", description: "Video, images, cameras, and live sources.", color: "#d86b45", icon: Film },
  { id: "games", title: "Games", description: "Playable and interactive experiences.", color: "#d86b45", icon: Gamepad2 },
  { id: "audio", title: "Audio", description: "Sound-reactive mappings and playback.", color: "#d86b45", icon: Music2 },
  { id: "visuals", title: "Visuals", description: "Generative art, effects, and shaders.", color: "#d86b45", icon: Sparkles },
  { id: "tools", title: "Tools", description: "Utilities, controls, and integrations.", color: "#d86b45", icon: Wrench },
] as const;
type DiscoverThemeId = typeof DISCOVER_THEMES[number]["id"];
const LISTING_TAGS = DISCOVER_THEMES.filter((theme): theme is typeof DISCOVER_THEMES[number] & { id: CommunityPackageTag } => theme.id !== "surreality");

function bytes(value: number) { if (value < 1024 * 1024) return `${Math.max(1, Math.round(value / 1024))} KB`; return `${(value / 1024 / 1024).toFixed(1)} MB`; }
function date(value: string | null | undefined) { return value ? new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", year: "numeric" }).format(new Date(value)) : "—"; }
function releaseName(release: CommunityRelease) { return release.listingName ?? release.manifest.name; }
function releaseDescription(release: CommunityRelease) { return release.listingDescription ?? release.manifest.description; }
function isNativeRelease(release: CommunityRelease) { return Boolean(release.manifest.entrypoints.plugin || release.manifest.permissions?.includes("system:unrestricted")); }
function isSurrealityRelease(release: CommunityRelease) { return release.packageId.startsWith("room.mapping.") || release.publisherUsername.toLowerCase() === "surreality" || release.manifest.author?.name.toLowerCase() === "surreality"; }
function discoverThemeFor(release: CommunityRelease): Exclude<DiscoverThemeId, "surreality"> {
  if (release.packageId === "room.mapping.sound") return "audio";
  const text = [release.packageId, releaseName(release), releaseDescription(release), ...(release.manifest.permissions ?? [])].join(" ").toLowerCase();
  if (/game|arcade|play|ship|physics|interactive/.test(text)) return "games";
  if (/audio|sound|music|beat|mic|spectrum/.test(text)) return "audio";
  if (/media|video|image|photo|camera|stream/.test(text)) return "media";
  if (/tool|util|control|remote|data|integration|midi|osc/.test(text)) return "tools";
  return "visuals";
}
function matchesDiscoverTheme(release: CommunityRelease, theme: DiscoverThemeId) { return theme === "surreality" ? isSurrealityRelease(release) : release.listingTags?.length ? release.listingTags.includes(theme) : discoverThemeFor(release) === theme; }
function progressId(operation: CommunityProgress["operation"], releaseId?: string) { return operation === "download" ? `download:${releaseId ?? "unknown"}` : "upload"; }
function localInstalledRelease(item: CustomMappingPackageRecord): CommunityRelease { return { releaseId: `local:${item.manifest.id}@${item.manifest.version}`, packageId: item.manifest.id, version: item.manifest.version, manifest: item.manifest, sha256: "", byteSize: 0, publisherUsername: item.manifest.author?.name ?? "Local package", status: "published", statusReason: null, approvedNative: Boolean(item.manifest.entrypoints.plugin || item.manifest.permissions?.includes("system:unrestricted")), publishedAt: null, createdAt: new Date(0).toISOString(), installed: true }; }
function compareVersions(left: string, right: string) {
  const [leftCore, leftPre] = left.split("-", 2); const [rightCore, rightPre] = right.split("-", 2);
  const leftParts = leftCore!.split(".").map(Number); const rightParts = rightCore!.split(".").map(Number);
  for (let index = 0; index < 3; index += 1) { const difference = (leftParts[index] ?? 0) - (rightParts[index] ?? 0); if (difference) return difference; }
  if (leftPre === rightPre) return 0; if (!leftPre) return 1; if (!rightPre) return -1;
  return leftPre.localeCompare(rightPre, undefined, { numeric: true });
}
function installStateFor(release: CommunityRelease, installed: ReturnType<typeof useCustomMappings>): InstallState {
  const versions = installed.filter(({ manifest }) => manifest.id === release.packageId).map(({ manifest }) => manifest.version);
  if (!versions.length) return "install";
  if (versions.includes(release.version)) return "installed";
  const newest = versions.sort(compareVersions).at(-1)!;
  return compareVersions(newest, release.version) < 0 ? "update" : "install";
}

function PackageMenu({ items }: { items: MenuItem[] }) {
  const menuRef = useRef<HTMLDetailsElement>(null);
  useEffect(() => {
    const closeOnOutsidePointer = (event: PointerEvent) => {
      if (!menuRef.current?.contains(event.target as Node)) menuRef.current?.removeAttribute("open");
    };
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") menuRef.current?.removeAttribute("open");
    };
    window.addEventListener("pointerdown", closeOnOutsidePointer);
    window.addEventListener("keydown", closeOnEscape, true);
    return () => {
      window.removeEventListener("pointerdown", closeOnOutsidePointer);
      window.removeEventListener("keydown", closeOnEscape, true);
    };
  }, []);
  if (!items.length) return null;
  return <details ref={menuRef} className="group/menu relative" onClick={(event) => event.stopPropagation()} onKeyDown={(event) => event.stopPropagation()}><summary className="flex size-8 cursor-pointer list-none items-center justify-center border border-white/10 bg-black/65 text-white/55 backdrop-blur-sm hover:bg-white/10 hover:text-white [&::-webkit-details-marker]:hidden" aria-label="Package actions"><Ellipsis className="size-4" /></summary><div className="absolute right-0 top-10 z-30 w-44 border border-white/12 bg-[#151519] p-1 shadow-2xl shadow-black/60">{items.map((item) => <button key={item.label} type="button" className={`flex h-9 w-full items-center gap-2.5 whitespace-nowrap px-2.5 text-left text-[11px] ${item.danger ? "text-danger hover:bg-danger/10" : "text-white/65 hover:bg-white/8 hover:text-white"}`} onClick={(event) => { (event.currentTarget.closest("details") as HTMLDetailsElement | null)?.removeAttribute("open"); item.action(); }}>{item.icon}<span>{item.label}</span></button>)}</div></details>;
}

function ProgressToastView({ toast, onClose }: { toast: ProgressToast; onClose: () => void }) {
  const complete = toast.status === "success"; const failed = toast.status === "error";
  return <div className={`w-full border bg-[#151519]/95 p-4 shadow-2xl shadow-black/60 backdrop-blur-md ${failed ? "border-danger/40" : complete ? "border-green-400/30" : "border-accent/30"}`} role={failed ? "alert" : "status"} aria-live="polite"><div className="flex items-start gap-3">{failed ? <AlertTriangle className="mt-0.5 size-4 shrink-0 text-danger" /> : complete ? <CheckCircle2 className="mt-0.5 size-4 shrink-0 text-green-400" /> : <ArrowDownToLine className="mt-0.5 size-4 shrink-0 text-accent motion-safe:animate-bounce" />}<div className="min-w-0 flex-1"><p className="font-mono text-[8px] uppercase tracking-[0.16em] text-white/30">{toast.operation === "download" ? "Package installation" : "Package upload"}</p><p className="mt-1 truncate text-[12px] font-medium text-white/80">{toast.title}</p><p className={`mt-1 text-[10px] ${failed ? "text-danger" : "text-white/45"}`}>{toast.message}</p></div><button type="button" onClick={onClose} className="-mr-1 -mt-1 flex size-7 shrink-0 items-center justify-center text-white/30 transition hover:bg-white/8 hover:text-white" aria-label={`Dismiss ${toast.title}`}><X className="size-3.5" /></button></div><div className="mt-3 flex items-center gap-3"><div className="h-1 flex-1 overflow-hidden bg-white/8"><div className={`h-full transition-[width,background-color] duration-300 ${failed ? "bg-danger" : complete ? "bg-green-400" : "bg-accent"}`} style={{ width: `${failed ? Math.max(4, toast.percent) : toast.percent}%` }} /></div><span className="w-8 text-right font-mono text-[9px] text-white/35">{toast.percent}%</span></div></div>;
}

function EmptyState({ title, detail, icon, actionLabel, onAction }: { title: string; detail?: string; icon?: ReactNode; actionLabel?: string; onAction?: () => void }) {
  return <div className="empty-state"><span className="empty-state-mark">{icon ?? <Boxes className="size-4" />}</span><strong>{title}</strong>{detail ? <small>{detail}</small> : null}{actionLabel && onAction ? <button type="button" onClick={onAction}>{actionLabel}</button> : null}</div>;
}

function PackageCardSkeleton({ delay = 0, className = "" }: { delay?: number; className?: string }) {
  return <article className={`ui-card relative overflow-hidden ${className}`} aria-hidden="true"><div className="relative aspect-[1.9/1] bg-white/[0.045] motion-safe:animate-pulse [animation-duration:1.4s]" style={{ animationDelay: `${delay}ms` }}><div className="absolute right-2.5 top-2.5 size-8 bg-white/[0.055]" /></div><div className="p-4"><div className="flex items-start justify-between gap-4"><div className="min-w-0 flex-1"><div className="h-3.5 w-3/5 bg-white/10 motion-safe:animate-pulse [animation-duration:1.4s]" style={{ animationDelay: `${delay + 70}ms` }} /><div className="mt-2 h-2 w-4/5 bg-white/5 motion-safe:animate-pulse [animation-duration:1.4s]" style={{ animationDelay: `${delay + 110}ms` }} /></div><div className="size-4 bg-white/5 motion-safe:animate-pulse [animation-duration:1.4s]" style={{ animationDelay: `${delay + 140}ms` }} /></div><div className="mt-4 h-2 w-full bg-white/[0.065] motion-safe:animate-pulse [animation-duration:1.4s]" style={{ animationDelay: `${delay + 170}ms` }} /><div className="mt-2 h-2 w-2/3 bg-white/[0.045] motion-safe:animate-pulse [animation-duration:1.4s]" style={{ animationDelay: `${delay + 210}ms` }} /></div></article>;
}

