  return <button type="button" onClick={onClick} className={`${large ? "h-11 text-[12px]" : "h-8 text-[11px]"} flex flex-1 items-center justify-center gap-2 font-semibold transition ${installed ? "border border-danger/45 bg-danger/10 text-danger hover:border-danger/70 hover:bg-danger/20" : "bg-accent text-black hover:bg-[#ff713d]"}`}>{installed ? <PackageMinus className="size-4" /> : <ArrowDownToLine className="size-3.5" />}{state === "installed" ? large ? "Uninstall package" : "Uninstall" : state === "update" ? "Update" : large ? "Install package" : "Install"}</button>;
